// 2. 强制走主库 - 注解方式
@Component
public class MasterSlaveRoute {
    private static final ThreadLocal<Boolean> FORCE_MASTER =
        ThreadLocal.withInitial(() -> false);

    public void forceMaster() {
        FORCE_MASTER.set(true);
    }

    public void clear() {
        FORCE_MASTER.remove();
    }

    public boolean isForceMaster() {
        return FORCE_MASTER.get();
    }
}

// 3. 写后读走主库
@Service
public class UserService {
    @Autowired
    private MasterSlaveRoute route;

    @Transactional
    public void updateUser(String userId, UserUpdateCmd cmd) {
        userMapper.update(userId, cmd);
        // 标记后续读走主库
        route.forceMaster();
    }

    public UserDTO getUser(String userId) {
        if (route.isForceMaster()) {
            // ShardingSphere Hint强制走主库
            HintManager.getInstance()
                .setWriteRouteOnly();
        }
        return userMapper.selectById(userId);
    }
}

// 4. 半同步复制配置
