// 6. 延迟检查
public boolean isSlaveCaughtUp() {
    // 检查从库延迟
    Map<String, Object> status = jdbcTemplate
        .queryForMap("SHOW SLAVE STATUS");
    Long secondsBehind = (Long) status.get("Seconds_Behind_Master");
    return secondsBehind != null && secondsBehind < 1;
}
